import type { FastifyInstance } from 'fastify';
import { z } from 'zod';
import type { AppContext } from '../../app.js';
import type { RestoreResponse } from '../../contract.js';
import { BackupScheduleSchema } from '../../backups/service.js';

const serverParams = z.object({ serverId: z.string().min(1).max(100) });
const backupParams = serverParams.extend({ backupId: z.string().min(1).max(100) });
const createBody = z.object({ includeConfig: z.boolean().optional() }).strict();

// file names are generated by the service; this keeps the header free of anything exotic regardless
const headerName = (name: string): string => name.replace(/[^A-Za-z0-9._-]/g, '_');

export function registerBackupRoutes(app: FastifyInstance, { services }: AppContext): void {
  const { backups } = services;

  app.get('/api/servers/:serverId/backups', async (request) => {
    const { serverId } = serverParams.parse(request.params);
    return backups.list(serverId);
  });

  app.post('/api/servers/:serverId/backups', async (request, reply) => {
    const { serverId } = serverParams.parse(request.params);
    const body = createBody.parse(request.body ?? {});
    const backup = await backups.start(serverId, 'manual', body.includeConfig);
    return reply.status(202).send({ backup });
  });

  app.patch('/api/servers/:serverId/backups/schedule', async (request) => {
    const { serverId } = serverParams.parse(request.params);
    return { schedule: await backups.setSchedule(serverId, BackupScheduleSchema.parse(request.body)) };
  });

  app.get('/api/servers/:serverId/backups/:backupId/download', async (request, reply) => {
    const { serverId, backupId } = backupParams.parse(request.params);
    const { row, file, size } = await backups.locate(serverId, backupId);
    void reply
      .header('Content-Type', 'application/gzip')
      .header('Content-Length', size)
      .header('Content-Disposition', `attachment; filename="${headerName(row.fileName)}"`)
      .header('Cache-Control', 'no-store');
    return reply.send(backups.openDownload(file));
  });

  app.post('/api/servers/:serverId/backups/:backupId/restore', async (request): Promise<RestoreResponse> => {
    const { serverId, backupId } = backupParams.parse(request.params);
    return backups.restore(serverId, backupId);
  });

  app.delete('/api/servers/:serverId/backups/:backupId', async (request) => {
    const { serverId, backupId } = backupParams.parse(request.params);
    await backups.remove(serverId, backupId);
    return { deleted: true };
  });
}
